python -c "import pandas as pd, numpy as np, spglib; from pymatgen.core import Structure; df=pd.read_csv('nlo_pool.csv'); print('Rows:',len(df)); print('ID   Formula                    SG             PG    Inversion  V/atom');
for r in df.itertuples():
 s=Structure.from_str(r.poscar,fmt='poscar'); cell=(s.lattice.matrix,s.frac_coords,s.atomic_numbers); d=spglib.get_symmetry_dataset(cell,symprec=0.01); inv=any(np.array_equal(x,-np.eye(3,dtype=int)) for x in d.rotations); print(f'{r.candidate_id} {r.formula:26s} {d.international:10s} {d.number:3d} {d.pointgroup:6s} {str(inv):5s} {s.volume/len(s):8.2f}')"

python -c "import pandas as pd,numpy as np; from pymatgen.core import Structure; df=pd.read_csv('nlo_pool.csv'); wanted=list(range(1,7))+list(range(8,20))+list(range(31,38))+[46,48,50,51,52,57,67,76,77,78,81,82,88]+list(range(94,100)); print('ID Formula element CNrange bond-range dist-to-centroid tensor-norm/V max-component/V tetra-coherence');
for r in df.itertuples():
 if int(r.candidate_id[1:]) not in wanted: continue
 s=Structure.from_str(r.poscar,fmt='poscar'); anions=set(s.symbol_set)&{'Se','S'}
 for el in [e for e in s.symbol_set if e not in anions and e not in ['Li','K','Rb','Ba','Cl']]:
  loc=[]; off=[]; bonds=[]; cns=[]
  for site in s:
   if site.specie.symbol!=el: continue
   ns=sorted([n for n in s.get_neighbors(site,4.2) if n.specie.symbol in anions],key=lambda n:n.nn_distance); n0=ns[0].nn_distance; ns=[n for n in ns if n.nn_distance<n0*1.22]; cns.append(len(ns)); vec=np.array([n.coords-site.coords for n in ns]); rr=np.linalg.norm(vec,axis=1); u=vec/rr[:,None]; loc.append(np.einsum('ni,nj,nk->ijk',u,u,u)); off.append(np.linalg.norm(vec.mean(axis=0))); bonds.extend(rr)
  t=sum(loc); print(r.candidate_id,r.formula,el,f'{min(cns)}-{max(cns)}',f'{min(bonds):.3f}-{max(bonds):.3f}',f'{np.mean(off):.3f}',f'{1000*np.linalg.norm(t)/s.volume:.2f}',f'{1000*np.max(abs(t))/s.volume:.2f}',f'{np.linalg.norm(t)/sum(np.linalg.norm(x) for x in loc):.3f}')"

python -c "import pandas as pd, numpy as np; from pymatgen.core import Structure; df=pd.read_csv('nlo_pool.csv'); selected={'c005','c016','c018','c025','c026','c028','c037','c041','c044','c050','c051','c052','c076','c077','c078','c081','c084','c085','c086','c088'}; radii={'C':0.76,'Si':1.11,'Be':0.96,'Ga':1.22,'Zn':1.22,'Al':1.21,'Ag':1.45,'Sc':1.7,'Y':1.9,'Mg':1.41,'B':0.84}; print('ID  reduced-formula     volume    largest bond tensor component by central species');
for r in df.itertuples():
 if r.candidate_id not in selected: continue
 s=Structure.from_str(r.poscar,fmt='poscar'); active=set(s.symbol_set)&set(radii); ligands=set(s.symbol_set)&{'C','S','Se','Cl'}; active-=ligands; out=[]
 for el in active:
  tensor=np.zeros((3,3,3)); nactive=0
  for site in s:
   if site.specie.symbol!=el:continue
   nn=sorted([n for n in s.get_neighbors(site,4.5) if n.specie.symbol in ligands],key=lambda n:n.nn_distance); nn=nn[:3 if el=='B' else 6 if el in ['Y','Sc'] else 4]; vs=np.array([n.coords-site.coords for n in nn]); rr=np.linalg.norm(vs,axis=1); u=vs/rr[:,None]; tensor+=np.einsum('ni,nj,nk->ijk',u,u,u); nactive+=1
  i=np.unravel_index(np.argmax(abs(tensor)),(3,3,3)); out.append((el,nactive,round(1000*abs(tensor[i])/s.volume,2),i))
 print(r.candidate_id,f'{s.composition.reduced_formula:19}',round(s.volume,1),out)"

python -c "import pandas as pd,numpy as np; from pymatgen.core import Structure; df=pd.read_csv('nlo_pool.csv'); ids={'c050','c051','c052','c076','c077','c078'}; print('Equal-bond and bond-length sensitivity: arbitrary geometric units, not d coefficients.'); print('ID  Ga density/1000A3  bond weight exponent -6, 0, +6 (largest weighted Ga-S component/V)');
for r in df.itertuples():
 if r.candidate_id not in ids:continue
 s=Structure.from_str(r.poscar,fmt='poscar'); scores=[]; sites=[x for x in s if x.specie.symbol=='Ga'];
 for p in [-6,0,6]:
  t=np.zeros((3,3,3))
  for site in sites:
   nn=sorted([n for n in s.get_neighbors(site,3) if n.specie.symbol=='S'],key=lambda n:n.nn_distance)[:4]; v=np.array([n.coords-site.coords for n in nn]); rr=np.linalg.norm(v,axis=1); u=v/rr[:,None]; t+=np.einsum('n,ni,nj,nk->ijk',(rr/2.33)**p,u,u,u)
  scores.append(round(1000*abs(t).max()/s.volume,3))
 print(r.candidate_id,round(1000*len(sites)/s.volume,3),scores)"

